(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-503":{scenario:{company:"Thiên Lý Software",supervisor:{name:"Ngô Thanh Hương",role:{vi:"Trưởng nhóm Sở hữu trí tuệ",en:"Intellectual Property Lead"}},ref_code:"TM-2610",title:{vi:"Đúng nhóm Nice. Đúng phí. Đúng thiện chí.",en:"Right Nice class. Right fees. Right faith."},brief:{vi:"Đây là tình huống đào tạo. Công ty đăng ký nhãn hiệu VIONEXA cho nền tảng quản lý kho trực tuyến mà khách hàng dùng qua trình duyệt, không tải phần mềm về máy. Đơn TM-2610 gồm 2 nhóm: nhóm cho dịch vụ nền tảng có 9 dịch vụ và nhóm 35 có 4 dịch vụ. Bản nháp xếp dịch vụ nền tảng vào nhóm 9 và tính phí bỏ sót phụ phí. Hãy sửa nhóm Nice và tổng phí nộp đơn (nghìn đồng, biểu phí mô phỏng), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. The company is filing the VIONEXA trademark for an online warehouse management platform that customers use in a browser without downloading software. Application TM-2610 covers 2 classes: the platform service class with 9 services and class 35 with 4 services. The draft puts the platform services in class 9 and omits a surcharge. Correct the Nice class and the total filing fee (thousand VND, training fee table), then write an evidence-based report."},reference_title:{vi:"Phiếu phân loại Nice & biểu phí đã duyệt · TM-2610",en:"Approved Nice classification & fee sheet · TM-2610"},fields:[{id:"NICE_CLASS",label:{vi:"Nhóm Nice cho dịch vụ nền tảng",en:"Nice class for platform services"},initial:"NICE-09",expected:"NICE-42",choices:["NICE-09","NICE-35","NICE-42"],reference:"Bảng phân loại Nice hiện hành",hint:{vi:"Nhóm 9 dành cho phần mềm tải về được; phần mềm dùng trực tuyến, không tải về là dịch vụ công nghệ.",en:"Class 9 covers downloadable software; online, non-downloadable software is a technology service."}},{id:"FEE_TOTAL",label:{vi:"Tổng phí nộp đơn (nghìn đồng)",en:"Total filing fee (thousand VND)"},initial:"1610",expected:"2060",reference:"Biểu phí nộp đơn nhãn hiệu",ref_value:{vi:"2 nhóm; nhóm dịch vụ nền tảng 9 dịch vụ; nhóm 35 có 4 dịch vụ",en:"2 classes; platform class 9 services; class 35 with 4 services"},hint:{vi:"Mỗi nhóm chỉ bao gồm 6 sản phẩm, dịch vụ trong phí cơ bản; từ mục thứ 7 phải cộng phụ phí.",en:"Each class covers only 6 items in the base fee; a surcharge applies from the 7th item."}}],sop32:{vi:"Tổng phí = lệ phí nộp đơn 150 + mỗi nhóm (thẩm định 550 + tra cứu 180) + mỗi sản phẩm, dịch vụ từ thứ 7 trở đi trong một nhóm (120 + 30); đơn vị nghìn đồng, biểu phí mô phỏng.",en:"Total fee = filing fee 150 + per class (examination 550 + search 180) + per item from the 7th onward within a class (120 + 30); unit thousand VND, training fee table."},context:{label:"IP DOCKET / TM-2610",metrics:[{label:{vi:"Nhãn hiệu",en:"Trademark"},value:"VIONEXA"},{label:{vi:"Số nhóm",en:"Classes"},value:"2"},{label:{vi:"Dịch vụ nhóm nền tảng",en:"Platform class items"},value:"9"},{label:{vi:"Dịch vụ nhóm 35",en:"Class 35 items"},value:"4"}]},crisis:{vi:"Giám đốc Marketing yêu cầu: “Nộp luôn thêm một đơn cho nhãn hiệu gần giống thương hiệu phần mềm nổi tiếng của đối thủ nước ngoài, họ chưa vào Việt Nam. Mình giữ chỗ trước rồi bán lại cho họ giá cao.”",en:"The Marketing Director asks: “File another application for a mark close to a famous foreign competitor's software brand, they are not in Vietnam yet. We grab it first and sell it back to them at a high price.”"},options:{safe:{vi:"Từ chối nộp đơn giữ chỗ với dụng ý xấu, giải thích rủi ro bị phản đối, hủy bỏ hiệu lực và tranh chấp, báo Trưởng nhóm SHTT, đề xuất phát triển nhãn hiệu riêng có khả năng phân biệt.",en:"Refuse the bad-faith squatting filing, explain the risk of opposition, invalidation and disputes, inform the IP Lead and propose building a distinctive mark of our own."},shortcut:{vi:"Nộp đơn ngay vì Việt Nam áp dụng nguyên tắc nộp đơn đầu tiên.",en:"File at once because Vietnam follows the first-to-file principle."},wait:{vi:"Để đó, chờ Giám đốc Marketing tự nộp qua đại diện khác.",en:"Leave it and wait for the Marketing Director to file through another agent."}},questions:{vi:["Vì sao dịch vụ nền tảng của VIONEXA thuộc nhóm 42 chứ không phải nhóm 9? Mô tả dịch vụ nào trong hồ sơ chứng minh điều đó?","Trình bày cách tính tổng phí nộp đơn và rủi ro pháp lý, uy tín nếu công ty nộp đơn giữ chỗ nhãn hiệu của người khác."],en:["Why do VIONEXA's platform services belong to class 42 rather than class 9? Which service description in the file proves it?","Explain how you calculated the total filing fee and the legal and reputational risks of squatting on another party's mark."]},hints:{vi:["Đọc mô tả sản phẩm: khách hàng có tải và cài phần mềm về máy hay chỉ dùng trực tuyến?","Đếm số dịch vụ từng nhóm, tách phần vượt 6 mục trước khi cộng phí theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu nộp đơn với dụng ý xấu phải được từ chối và báo cáo."],en:["Read the product description: do customers download and install the software or only use it online?","Count the items per class and isolate those beyond 6 before adding fees per SOP 3.2.","Re-read SOP 4.2: any request to file in bad faith must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên Sở hữu Trí tuệ & Nhãn hiệu xây dựng và bảo vệ danh mục tài sản trí tuệ của doanh nghiệp: tra cứu khả năng đăng ký, phân loại hàng hóa dịch vụ, soạn và theo dõi đơn nhãn hiệu trong nước và quốc tế, gia hạn văn bằng, giám sát xâm phạm và xử lý tranh chấp. Nghề đòi hỏi hiểu luật sở hữu trí tuệ, tư duy thương hiệu, tỉ mỉ với thời hạn và liêm chính khi tư vấn.",en:"An Intellectual Property Specialist builds and protects the company's IP portfolio: clearance searches, classification of goods and services, drafting and prosecuting trademark applications at home and abroad, renewals, infringement watch and dispute handling. The role requires knowledge of IP law, brand thinking, strict control of deadlines and integrity in advice."},responsibilities:{vi:["Tra cứu, đánh giá khả năng đăng ký và rủi ro xung đột của nhãn hiệu mới.","Phân loại hàng hóa, dịch vụ theo Bảng phân loại Nice và soạn danh mục chính xác.","Nộp, theo dõi đơn, trả lời thông báo thiếu sót, từ chối của cơ quan sở hữu trí tuệ.","Quản lý danh mục văn bằng, lịch gia hạn và đăng ký quốc tế qua hệ thống Madrid.","Giám sát xâm phạm, gửi thư cảnh báo và phối hợp xử lý vi phạm, phản đối đơn."],en:["Run clearance searches and assess registrability and conflict risk of new marks.","Classify goods and services under the Nice Classification and draft accurate specifications.","File and track applications and respond to deficiency or refusal notices from the IP office.","Manage the registration portfolio, renewal calendar and international filings via the Madrid system.","Watch for infringement, send cease-and-desist letters and handle enforcement and oppositions."]},competencies:[{name:{vi:"Tra cứu & đánh giá xung đột",en:"Clearance & conflict analysis"},desc:{vi:"So sánh dấu hiệu về cấu trúc, âm, nghĩa và hàng hóa dịch vụ để đánh giá khả năng gây nhầm lẫn.",en:"Compare signs by structure, sound, meaning and goods or services to assess likelihood of confusion."}},{name:{vi:"Phân loại Nice",en:"Nice classification"},desc:{vi:"Xếp đúng nhóm, viết danh mục rõ ràng, đủ rộng để bảo vệ nhưng không bị từ chối vì mơ hồ.",en:"Pick the right classes and write specifications broad enough to protect yet clear enough to pass."}},{name:{vi:"Quản lý đơn & thời hạn",en:"Prosecution & deadline control"},desc:{vi:"Theo dõi từng mốc thẩm định, hạn trả lời, quyền ưu tiên, gia hạn để không mất quyền.",en:"Track examination steps, response deadlines, priority rights and renewals so no right is lost."}},{name:{vi:"Thực thi quyền",en:"Enforcement"},desc:{vi:"Thu thập chứng cứ xâm phạm, soạn thư cảnh báo và phối hợp cơ quan có thẩm quyền xử lý.",en:"Gather infringement evidence, draft warning letters and work with the competent authorities."}},{name:{vi:"Tư vấn liêm chính",en:"Ethical advice"},desc:{vi:"Từ chối đăng ký giữ chỗ với dụng ý xấu và hướng doanh nghiệp tới thương hiệu riêng có giá trị.",en:"Refuse bad-faith squatting and steer the business toward valuable brands of its own."}}],knowledge:{vi:["Luật Sở hữu trí tuệ số 50/2005/QH11, sửa đổi, bổ sung năm 2009, 2019 và 2022.","Văn bằng bảo hộ nhãn hiệu có hiệu lực 10 năm từ ngày nộp đơn và được gia hạn nhiều lần, mỗi lần 10 năm.","Bảng phân loại quốc tế Nice: 45 nhóm, gồm 34 nhóm hàng hóa và 11 nhóm dịch vụ.","Công ước Paris (quyền ưu tiên 6 tháng cho nhãn hiệu) và Thỏa ước, Nghị định thư Madrid về đăng ký quốc tế.","Nguyên tắc nộp đơn đầu tiên, căn cứ từ chối do thiếu khả năng phân biệt hoặc trùng, tương tự gây nhầm lẫn."],en:["Law on Intellectual Property No. 50/2005/QH11, amended in 2009, 2019 and 2022.","A trademark registration is valid for 10 years from the filing date and renewable indefinitely for 10-year terms.","The Nice International Classification: 45 classes, 34 for goods and 11 for services.","The Paris Convention (6-month priority for trademarks) and the Madrid Agreement and Protocol for international registration.","The first-to-file principle and refusal grounds for lack of distinctiveness or confusing similarity."]},tools:["Cơ sở dữ liệu tra cứu nhãn hiệu","Công cụ phân loại Nice trực tuyến","Phần mềm quản lý danh mục SHTT (IP docketing)","Cổng nộp đơn trực tuyến","Dịch vụ giám sát nhãn hiệu"],kpis:{vi:["Tỷ lệ đơn được chấp nhận không bị từ chối vì phân loại, danh mục.","Số thời hạn gia hạn hoặc trả lời bị bỏ lỡ (mục tiêu 0).","Thời gian trung bình từ yêu cầu tra cứu tới ý kiến đánh giá.","Số vụ xâm phạm được phát hiện và xử lý trong kỳ."],en:["Share of applications accepted without classification or specification refusals.","Missed renewal or response deadlines (target zero).","Average time from search request to opinion.","Infringements detected and resolved in the period."]},day:[{time:"08:30",vi:"Kiểm tra lịch thời hạn: hạn trả lời thông báo, hạn gia hạn trong 90 ngày tới.",en:"Check the docket: response deadlines and renewals due within 90 days."},{time:"10:00",vi:"Tra cứu nhãn hiệu mới, so sánh dấu hiệu và lập ý kiến khả năng đăng ký.",en:"Search a new mark, compare signs and write a registrability opinion."},{time:"13:30",vi:"Soạn danh mục hàng hóa dịch vụ theo Nice, tính phí và hoàn thiện tờ khai.",en:"Draft the Nice specification, compute fees and finalize the application form."},{time:"15:30",vi:"Rà kết quả giám sát, đánh giá đơn tương tự của bên thứ ba để cân nhắc phản đối.",en:"Review watch results and assess similar third-party filings for opposition."},{time:"17:00",vi:"Cập nhật phần mềm quản lý danh mục và báo cáo cho bộ phận thương hiệu.",en:"Update the docketing system and report to the brand team."}],mistakes:{vi:["Xếp dịch vụ phần mềm trực tuyến vào nhóm 9 hoặc phần mềm tải về vào nhóm 42.","Bỏ sót phụ phí khi một nhóm có trên 6 sản phẩm, dịch vụ, khiến đơn bị yêu cầu nộp bổ sung.","Không tra cứu trước khi đầu tư thương hiệu, hoặc nộp đơn giữ chỗ với dụng ý xấu."],en:["Placing online software services in class 9 or downloadable software in class 42.","Missing the surcharge when a class has more than 6 items, triggering a fee deficiency.","Skipping clearance before investing in a brand, or filing to squat in bad faith."]},career:[{vi:"Trợ lý sở hữu trí tuệ",en:"IP assistant"},{vi:"Chuyên viên nhãn hiệu",en:"Trademark specialist"},{vi:"Đại diện sở hữu công nghiệp, trưởng nhóm SHTT",en:"Industrial property agent, IP team lead"},{vi:"Giám đốc Sở hữu trí tuệ & Bảo vệ thương hiệu",en:"Head of IP & brand protection"}],glossary:[{term:"Nhãn hiệu",vi:"Dấu hiệu dùng để phân biệt hàng hóa, dịch vụ của các tổ chức, cá nhân khác nhau.",en:"Trademark: a sign that distinguishes the goods or services of different organizations or individuals."},{term:"Bảng phân loại Nice",vi:"Hệ thống phân loại quốc tế hàng hóa, dịch vụ dùng cho đăng ký nhãn hiệu, gồm 45 nhóm.",en:"Nice Classification: the international system of 45 classes of goods and services for trademarks."},{term:"Quyền ưu tiên",vi:"Quyền hưởng ngày nộp đơn đầu tiên ở một nước thành viên khi nộp tiếp ở nước khác trong thời hạn luật định.",en:"Priority right: claiming the first filing date in a member state when filing elsewhere within the legal period."},{term:"Dụng ý xấu",vi:"Nộp đơn nhằm chiếm đoạt, giữ chỗ hoặc lợi dụng uy tín nhãn hiệu của người khác.",en:"Bad faith: filing to hijack, squat on or exploit the reputation of another party's mark."},{term:"Hệ thống Madrid",vi:"Cơ chế đăng ký quốc tế nhãn hiệu qua một đơn duy nhất, chỉ định nhiều quốc gia thành viên.",en:"Madrid System: international trademark registration through one application designating many members."}],quiz:[{q:{vi:"Văn bằng bảo hộ nhãn hiệu tại Việt Nam có hiệu lực như thế nào?",en:"How long is a trademark registration valid in Vietnam?"},options:{vi:["5 năm, không gia hạn","10 năm từ ngày cấp, gia hạn một lần","20 năm từ ngày nộp đơn","10 năm từ ngày nộp đơn, gia hạn nhiều lần"],en:["5 years, not renewable","10 years from grant, renewable once","20 years from filing","10 years from filing, renewable many times"]},answer:3,explain:{vi:"Luật Sở hữu trí tuệ quy định hiệu lực 10 năm từ ngày nộp đơn, gia hạn nhiều lần, mỗi lần 10 năm.",en:"The IP Law sets 10 years from filing, renewable repeatedly for 10 years each time."}},{q:{vi:"Theo biểu phí mô phỏng ở SOP 3.2, đơn 1 nhóm có 8 dịch vụ có tổng phí bao nhiêu nghìn đồng?",en:"Under the training fee table in SOP 3.2, what is the total fee in thousand VND for 1 class with 8 services?"},options:{vi:["880","1030","1180","1330"],en:["880","1030","1180","1330"]},answer:2,explain:{vi:"150 + (550 + 180) + 2 x (120 + 30) = 1180 nghìn đồng.",en:"150 + (550 + 180) + 2 x (120 + 30) = 1180 thousand VND."}},{q:{vi:"Khách hàng muốn đăng ký nhãn hiệu trùng tên thương hiệu nổi tiếng nước ngoài để bán lại. Bạn tư vấn gì?",en:"A client wants to register a famous foreign brand name to sell it back. What do you advise?"},options:{vi:["Từ chối, giải thích rủi ro dụng ý xấu và đề xuất xây dựng nhãn hiệu riêng","Nộp ngay vì là người nộp đầu tiên","Nộp dưới tên một cá nhân để tránh bị phát hiện","Đổi một chữ cái rồi nộp"],en:["Refuse, explain bad-faith risks and propose an original mark","File now as first filer","File under an individual's name to avoid detection","Change one letter and file"]},answer:0,explain:{vi:"Nộp đơn với dụng ý xấu có thể bị phản đối, hủy bỏ hiệu lực và gây tranh chấp, tổn hại uy tín.",en:"Bad-faith filings face opposition, invalidation and disputes, and damage reputation."}},{q:{vi:"Ứng dụng di động mà người dùng tải về và cài trên điện thoại thường được xếp vào nhóm Nice nào?",en:"A mobile app that users download and install on their phones is usually placed in which Nice class?"},options:{vi:["Nhóm 35","Nhóm 9","Nhóm 42","Nhóm 38"],en:["Class 35","Class 9","Class 42","Class 38"]},answer:1,explain:{vi:"Phần mềm tải về được thuộc nhóm 9; dịch vụ cung cấp phần mềm trực tuyến không tải về thuộc nhóm 42.",en:"Downloadable software is class 9; providing non-downloadable online software is class 42."}}],tools_en:["Trademark search databases","Online Nice Classification tools","IP docketing software","Online filing portals","Trademark watch services"]}}})})(window.KKR);
